import math
import sympy
from sympy.ntheory import primefactors, factorint

N_HYP = 2
NEG_Q_INDEX = 2

CONDITION_LABELS = [
    "H_1: n > 1 is an integer",
    "H_2: R is the quotient ring Z/nZ",
    "¬Q: The nilradical of R is not the principal ideal generated by the congruence class of the product p_1...p_k"
]

def conditions(witness) -> list[bool]:
    try:
        if isinstance(witness, tuple):
            n_raw = witness[0]
            if len(witness) == 2 and isinstance(witness[1], (list, tuple)):
                p_list_raw = witness[1]
            else:
                p_list_raw = witness[1:]
        else:
            n_raw = witness
            p_list_raw = None

        if isinstance(n_raw, (int, sympy.Integer)):
            n = int(n_raw)
            if p_list_raw is not None:
                p_list = [int(x) for x in p_list_raw]
            else:
                factors = factorint(n)
                p_list = []
                for p, e in factors.items():
                    p_list.extend([p] * e)
        else:
            n = n_raw
            p_list = []
    except Exception:
        n = witness
        p_list = []

    # H_1: n > 1 is an integer
    try:
        h1 = isinstance(n, int) and n > 1
    except Exception:
        h1 = False

    # H_2: R is the quotient ring Z/nZ
    # This is a definitional hypothesis; it holds if n is valid.
    try:
        h2 = h1
    except Exception:
        h2 = False

    # neg_Q: The nilradical of R is NOT the principal ideal generated by the product p_1...p_k
    try:
        if not h1:
            neg_q = False
        else:
            # The actual nilradical of Z/nZ is generated by the product of its distinct prime factors
            actual_gen = 1
            for p in primefactors(n):
                actual_gen *= p
            
            # The claimed generator is the product of the provided p_1...p_k
            P = 1
            for p in p_list:
                P *= p
            
            # In Z/nZ, the principal ideal (P) is equal to the principal ideal (gcd(P, n))
            claimed_gen = math.gcd(P, n)
            
            # The conclusion fails if the actual generator and claimed generator produce different ideals
            neg_q = bool(actual_gen != claimed_gen)
    except Exception:
        neg_q = False

    return [h1, h2, neg_q]